  function replaceModel() {
    const section = document.getElementById("hh-model");
    if (!section) return;

    const appendParts = (parent, parts) => {
      parts.forEach((part) => {
        parent.appendChild(part instanceof Node ? part : document.createTextNode(String(part)));
      });
      return parent;
    };

    const symbol = (base, subscript = "", superscript = "") => {
      const span = el(
        "span",
        "inline-flex items-baseline whitespace-nowrap [font-family:Garamond,Georgia,'Times_New_Roman',serif] font-semibold italic",
      );
      span.appendChild(document.createTextNode(base));
      if (subscript) span.appendChild(el("sub", "ml-px text-[0.68em] not-italic", subscript));
      if (superscript) span.appendChild(el("sup", "ml-px text-[0.68em] not-italic", superscript));
      return span;
    };

    const fraction = (numerator, denominator) => {
      const wrap = el(
        "span",
        "mx-1 inline-flex flex-col items-center justify-center align-middle text-[0.82em] font-semibold leading-none",
      );
      const top = el("span", "border-b border-gray-900 px-1 pb-0.5 italic");
      const bottom = el("span", "px-1 pt-0.5 italic");
      appendParts(top, numerator);
      appendParts(bottom, denominator);
      wrap.append(top, bottom);
      return wrap;
    };

    const equationRow = (parts, className = "") => {
      const row = el(
        "div",
        "min-w-max whitespace-nowrap text-center [font-family:Garamond,Georgia,'Times_New_Roman',serif] font-semibold italic text-gray-950 " +
          className,
      );
      row.style.width = "max-content";
      row.style.marginInline = "auto";
      appendParts(row, parts);
      return row;
    };

    const rate = (letter, gate, suffix = "(V)") => {
      const span = el("span", "inline-flex items-baseline whitespace-nowrap");
      span.append(symbol(letter, gate), document.createTextNode(suffix));
      return span;
    };

    section.innerHTML = "";
    section.className = classes.section;
    section.appendChild(label("THEORETICAL MODEL & MATHEMATICAL DERIVATION"));

    const body = el("div", "space-y-6");

    const formulation = el("div", "space-y-3");
    formulation.appendChild(el("h3", classes.h3, "The Hodgkin-Huxley Formulation"));
    const introduction = el("p", classes.p);
    introduction.append(
      document.createTextNode(
        "In 1952, Hodgkin and Huxley introduced a system of differential equations for the membrane potential ",
      ),
      symbol("V"),
      document.createTextNode(", with a resting baseline of approximately −70 mV."),
    );
    formulation.appendChild(introduction);

    const formulationCard = el(
      "div",
      "rounded-lg border border-gray-200 bg-white p-5 md:p-7 space-y-6 overflow-hidden",
    );
    const formulaLabel = (text) => el("div", classes.h4 + " mb-3", text);

    const membraneBalance = el("div", "overflow-x-auto");
    membraneBalance.append(
      formulaLabel("Membrane Balance"),
      equationRow(
        [
          symbol("C", "m"),
          fraction(["dV"], ["dt"]),
          " = ",
          symbol("I", "app"),
          " − (",
          symbol("I", "Na"),
          " + ",
          symbol("I", "K"),
          " + ",
          symbol("I", "L"),
          ")",
        ],
        "text-2xl sm:text-3xl py-2",
      ),
    );

    const ionicEquations = el("div", "overflow-x-auto");
    ionicEquations.appendChild(formulaLabel("Ionic Equations"));
    const ionicGrid = el(
      "div",
      "grid gap-7 py-1",
    );
    ionicGrid.style.gridTemplateColumns = "repeat(3, minmax(220px, 1fr))";
    ionicGrid.style.minWidth = "760px";
    ionicGrid.append(
      equationRow(
        [
          symbol("I", "Na"),
          " = ",
          symbol("g", "Na"),
          symbol("m", "", "3"),
          "h(V − ",
          symbol("E", "Na"),
          ")",
        ],
        "text-xl sm:text-2xl",
      ),
      equationRow(
        [
          symbol("I", "K"),
          " = ",
          symbol("g", "K"),
          symbol("n", "", "4"),
          "(V − ",
          symbol("E", "K"),
          ")",
        ],
        "text-xl sm:text-2xl",
      ),
      equationRow(
        [
          symbol("I", "L"),
          " = ",
          symbol("g", "L"),
          "(V − ",
          symbol("E", "L"),
          ")",
        ],
        "text-xl sm:text-2xl",
      ),
    );
    ionicEquations.appendChild(ionicGrid);

    const finalEquation = el("div", "border-t border-gray-200 pt-6 overflow-x-auto");
    finalEquation.append(
      formulaLabel("Final Membrane Capacitance"),
      equationRow(
        [
        symbol("C", "m"),
        fraction(["dV"], ["dt"]),
        " = ",
        symbol("I", "app"),
        " − ",
        symbol("g", "Na"),
        symbol("m", "", "3"),
        "h(V − ",
        symbol("E", "Na"),
        ") − ",
        symbol("g", "K"),
        symbol("n", "", "4"),
        "(V − ",
        symbol("E", "K"),
        ") − ",
        symbol("g", "L"),
        "(V − ",
        symbol("E", "L"),
        ")",
        ],
        "text-xl sm:text-2xl py-2",
      ),
    );
    formulationCard.append(membraneBalance, ionicEquations, finalEquation);
    formulation.appendChild(formulationCard);

    const termInspector = el("div", "space-y-3");
    termInspector.appendChild(el("div", classes.h4 + " text-gray-900", "Tap a Term"));
    const termStrip = el("div", "pb-2");
    termStrip.dataset.hhTermStrip = "true";
    Object.assign(termStrip.style, {
      display: "grid",
      gap: "6px",
      gridTemplateColumns: "repeat(15, minmax(0, 1fr))",
      paddingBottom: "8px",
    });
    if (!document.getElementById("hh-term-strip-responsive")) {
      const style = el("style");
      style.id = "hh-term-strip-responsive";
      style.textContent = `
        @media (max-width: 900px) {
          [data-hh-term-strip="true"] {
            grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
          }
        }
      `;
      document.head.appendChild(style);
    }
    termStrip.setAttribute("role", "group");
    termStrip.setAttribute("aria-label", "Hodgkin-Huxley equation terms");

    const termExplanation = el(
      "div",
      "mt-5 border-l-4 border-red-500 bg-red-50/40 px-5 py-4",
    );
    const termExplanationTitle = el(
      "div",
      "mb-2 flex items-baseline gap-2 font-mono text-[15px] font-extrabold uppercase text-gray-950",
    );
    const termExplanationDetail = el(
      "p",
      "text-[17px] sm:text-[18px] text-gray-800 leading-relaxed font-sans",
    );
    termExplanation.append(termExplanationTitle, termExplanationDetail);

    const glossaryTerms = [
      {
        key: "cm",
        notation: ["C", "m"],
        title: "Membrane Capacitance",
        detail: "Charge-storage capacity of the lipid bilayer.",
      },
      {
        key: "v",
        notation: ["V"],
        title: "Membrane Potential",
        detail: "Voltage difference between the inside and outside of the neuron.",
      },
      {
        key: "iapp",
        notation: ["I", "app"],
        title: "Applied Current",
        detail: "Externally injected stimulus current that shifts the membrane voltage.",
      },
      {
        key: "ina",
        notation: ["I", "Na"],
        title: "Sodium Current",
        detail: "Inward sodium current that drives rapid depolarization.",
      },
      {
        key: "ik",
        notation: ["I", "K"],
        title: "Potassium Current",
        detail: "Outward potassium current that repolarizes the membrane.",
      },
      {
        key: "il",
        notation: ["I", "L"],
        title: "Leak Current",
        detail: "Passive background current that supports the resting potential.",
      },
      {
        key: "gna",
        notation: ["g", "Na"],
        title: "Sodium Conductance",
        detail: "Maximum conductance of the voltage-gated sodium channels.",
      },
      {
        key: "m",
        notation: ["m"],
        title: "Sodium Activation Gate",
        detail: "Fast activation variable controlling sodium-channel opening. Opens rapidly to drive upstroke depolarization.",
      },
      {
        key: "h",
        notation: ["h"],
        title: "Sodium Inactivation Gate",
        detail: "Inactivation variable controlling sodium-channel availability. Closes progressively at high voltages to terminate sodium influx.",
      },
      {
        key: "ena",
        notation: ["E", "Na"],
        title: "Sodium Reversal Potential",
        detail: "Voltage at which the net sodium current is zero.",
      },
      {
        key: "gk",
        notation: ["g", "K"],
        title: "Potassium Conductance",
        detail: "Maximum conductance of the voltage-gated potassium channels.",
      },
      {
        key: "n",
        notation: ["n"],
        title: "Potassium Activation Gate",
        detail: "Activation variable controlling potassium-channel opening. Opens slowly to allow outward potassium flow and repolarize the membrane.",
      },
      {
        key: "ek",
        notation: ["E", "K"],
        title: "Potassium Reversal Potential",
        detail: "Voltage at which the net potassium current is zero.",
      },
      {
        key: "gl",
        notation: ["g", "L"],
        title: "Leak Conductance",
        detail: "Constant conductance of the passive leak pathway.",
      },
      {
        key: "el",
        notation: ["E", "L"],
        title: "Leak Reversal Potential",
        detail: "Voltage at which the net leak current is zero.",
      },
    ];

    const termButtons = new Map();
    const setActiveTerm = (term) => {
      termExplanationTitle.innerHTML = "";
      termExplanationTitle.append(
        symbol(term.notation[0], term.notation[1] || ""),
        document.createTextNode("· " + term.title),
      );
      termExplanationDetail.textContent = term.detail;
      termButtons.forEach((button, key) => {
        const active = key === term.key;
        button.className =
          "flex h-14 shrink-0 items-center justify-center rounded-md border bg-white px-4 text-gray-700 transition-colors " +
          (active
            ? "border-gray-900 text-gray-950 shadow-sm"
            : "border-gray-200 hover:border-red-500 hover:text-red-600");
        button.setAttribute("aria-pressed", String(active));
      });
    };

    glossaryTerms.forEach((term) => {
      const button = el("button");
      button.type = "button";
      Object.assign(button.style, {
        alignItems: "center",
        display: "flex",
        height: "48px",
        justifyContent: "center",
        minWidth: "0",
        paddingInline: "4px",
        width: "100%",
      });
      button.setAttribute("aria-label", term.title);
      const notation = symbol(term.notation[0], term.notation[1] || "");
      notation.className += " text-[17px] font-extrabold";
      button.appendChild(notation);
      button.addEventListener("click", () => setActiveTerm(term));
      termButtons.set(term.key, button);
      termStrip.appendChild(button);
    });
    termInspector.append(termStrip, termExplanation);
    setActiveTerm(glossaryTerms.find((term) => term.key === "iapp"));

    const gates = el("div", "space-y-5");
    gates.appendChild(
      el(
        "h3",
        "font-mono text-2xl sm:text-3xl font-black text-gray-950",
        "Gating Variable Differential Equations",
      ),
    );
    gates.appendChild(
      el(
        "p",
        classes.p,
        "These gate variables describe how ion channels change state during an action potential. Sodium activation m opens quickly to start depolarization, sodium inactivation h closes to limit sodium entry, and potassium activation n opens more slowly to repolarize the membrane.",
      ),
    );

    if (!document.getElementById("gate-module-responsive")) {
      const gateStyle = el("style");
      gateStyle.id = "gate-module-responsive";
      gateStyle.textContent = `
        @media (max-width: 900px) {
          [data-gate-equation-row="true"] {
            grid-template-columns: 1fr !important;
            gap: 0.75rem !important;
          }
          [data-gate-equation="true"] {
            font-size: 24px !important;
            justify-self: start !important;
            margin-inline: 0 !important;
          }
          [data-gate-term-strip="true"] {
            grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
          }
        }
        [data-gate-term-strip="true"] button:focus {
          outline: none !important;
        }
        [data-gate-term-strip="true"] button[aria-pressed="true"] {
          border-color: #111827 !important;
          box-shadow: 0 1px 2px rgba(17, 24, 39, 0.08) !important;
          color: #111827 !important;
        }
      `;
      document.head.appendChild(gateStyle);
    }

    const gateCard = el(
      "div",
      "rounded-lg border border-gray-200 bg-white overflow-hidden",
    );
    const gateRows = [
      {
        label: "1. Sodium Activation Gate",
        equation: [
          fraction(["dm"], ["dt"]),
          " = ",
          rate("α", "m"),
          "(1 − m) − ",
          rate("β", "m"),
          "m",
        ],
      },
      {
        label: "2. Sodium Inactivation Gate",
        equation: [
          fraction(["dh"], ["dt"]),
          " = ",
          rate("α", "h"),
          "(1 − h) − ",
          rate("β", "h"),
          "h",
        ],
      },
      {
        label: "3. Potassium Activation Gate",
        equation: [
          fraction(["dn"], ["dt"]),
          " = ",
          rate("α", "n"),
          "(1 − n) − ",
          rate("β", "n"),
          "n",
        ],
      },
    ];
    gateRows.forEach((gate, index) => {
      const row = el("div", "p-5 md:p-6");
      row.dataset.gateEquationRow = "true";
      Object.assign(row.style, {
        alignItems: "center",
        display: "grid",
        gap: "24px",
        gridTemplateColumns: "minmax(220px, 0.72fr) minmax(440px, 1.28fr)",
      });
      if (index > 0) row.style.borderTop = "1px solid #e5e7eb";
      row.appendChild(
        el(
          "div",
          "font-mono text-xs font-extrabold uppercase text-red-600",
          gate.label,
        ),
      );
      const gateEquation = equationRow(gate.equation);
      gateEquation.dataset.gateEquation = "true";
      gateEquation.style.fontSize = "30px";
      row.appendChild(gateEquation);
      gateCard.appendChild(row);
    });
    gates.appendChild(gateCard);

    const gateInspector = el("div", "space-y-3");
    gateInspector.appendChild(el("div", classes.h4 + " text-gray-900", "Tap a Term"));
    const gateTermStrip = el("div");
    gateTermStrip.dataset.gateTermStrip = "true";
    gateTermStrip.setAttribute("role", "group");
    gateTermStrip.setAttribute("aria-label", "Gating equation terms");
    Object.assign(gateTermStrip.style, {
      display: "grid",
      gap: "8px",
      gridTemplateColumns: "repeat(10, minmax(0, 1fr))",
    });

    const gateExplanation = el(
      "div",
      "mt-5 border-l-4 border-red-500 bg-red-50/40 px-5 py-4",
    );
    const gateExplanationTitle = el(
      "div",
      "mb-2 flex items-baseline gap-2 font-mono text-[15px] font-extrabold uppercase text-gray-950",
    );
    const gateExplanationDetail = el(
      "p",
      "text-[17px] sm:text-[18px] text-gray-800 leading-relaxed font-sans",
    );
    gateExplanation.append(gateExplanationTitle, gateExplanationDetail);

    const gateTerms = [
      {
        key: "m",
        base: "m",
        title: "Sodium Activation Gate",
        detail: "Fraction of sodium activation gates that are open. Opens rapidly to drive upstroke depolarization.",
      },
      {
        key: "alpha-m",
        base: "α",
        sub: "m",
        suffix: "(V)",
        title: "Sodium Activation Rate",
        detail: "Voltage-dependent rate at which sodium activation gates open.",
      },
      {
        key: "beta-m",
        base: "β",
        sub: "m",
        suffix: "(V)",
        title: "Sodium Deactivation Rate",
        detail: "Voltage-dependent rate at which sodium activation gates close.",
      },
      {
        key: "h",
        base: "h",
        title: "Sodium Inactivation Gate",
        detail: "Fraction of sodium channels that remain available to conduct. Closes progressively at high voltages to terminate sodium influx.",
      },
      {
        key: "alpha-h",
        base: "α",
        sub: "h",
        suffix: "(V)",
        title: "Inactivation Recovery Rate",
        detail: "Voltage-dependent rate at which sodium channels recover from inactivation.",
      },
      {
        key: "beta-h",
        base: "β",
        sub: "h",
        suffix: "(V)",
        title: "Sodium Inactivation Rate",
        detail: "Voltage-dependent rate at which sodium channels become inactivated.",
      },
      {
        key: "n",
        base: "n",
        title: "Potassium Activation Gate",
        detail: "Fraction of potassium activation gates that are open. Opens slowly to allow outward potassium flow and repolarize the membrane.",
      },
      {
        key: "alpha-n",
        base: "α",
        sub: "n",
        suffix: "(V)",
        title: "Potassium Activation Rate",
        detail: "Voltage-dependent rate at which potassium activation gates open.",
      },
      {
        key: "beta-n",
        base: "β",
        sub: "n",
        suffix: "(V)",
        title: "Potassium Deactivation Rate",
        detail: "Voltage-dependent rate at which potassium activation gates close.",
      },
      {
        key: "v",
        base: "V",
        title: "Membrane Potential",
        detail: "Voltage across the neural membrane that controls all gate-transition rates.",
      },
    ];
    const renderGateTerm = (term) => {
      if (term.suffix) return rate(term.base, term.sub, term.suffix);
      return symbol(term.base, term.sub || "");
    };
    const gateTermButtons = new Map();
    const setActiveGateTerm = (term) => {
      gateExplanationTitle.innerHTML = "";
      gateExplanationTitle.append(
        renderGateTerm(term),
        document.createTextNode("· " + term.title),
      );
      gateExplanationDetail.textContent = term.detail;
      gateTermButtons.forEach((button, key) => {
        const active = key === term.key;
        button.className =
          "flex items-center justify-center rounded-md border bg-white text-gray-700 transition-colors " +
          (active
            ? "border-gray-900 text-gray-950 shadow-sm"
            : "border-gray-200 hover:border-red-500 hover:text-red-600");
        button.setAttribute("aria-pressed", String(active));
      });
    };
    gateTerms.forEach((term) => {
      const button = el("button");
      button.type = "button";
      button.setAttribute("aria-label", term.title);
      Object.assign(button.style, {
        height: "56px",
        minWidth: "0",
        paddingInline: "4px",
        width: "100%",
      });
      const notation = renderGateTerm(term);
      notation.className += " text-[17px] font-extrabold";
      button.appendChild(notation);
      button.addEventListener("click", () => setActiveGateTerm(term));
      gateTermButtons.set(term.key, button);
      gateTermStrip.appendChild(button);
    });
    gateInspector.append(gateTermStrip, gateExplanation);
    setActiveGateTerm(gateTerms.find((term) => term.key === "alpha-h"));
    gates.appendChild(gateInspector);

    // --- thermodynamic Nernst formulation ---
    const frac = (num, den) =>
      '<span style="display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.2">' +
      '<span style="padding:0 .4em">' + num + '</span>' +
      '<span style="padding:0 .4em;border-top:1.5px solid currentColor">' + den + '</span></span>';
    const bigParen = (inner) =>
      '<span style="font-size:1.9em;font-weight:400;vertical-align:middle">(</span>' + inner +
      '<span style="font-size:1.9em;font-weight:400;vertical-align:middle">)</span>';
    const KO = "[K<sup>+</sup>]<sub>o</sub>", KI = "[K<sup>+</sup>]<sub>i</sub>";

    const nernst = el("div", "mt-8");
    nernst.append(
      el("h3", classes.h3, "Thermodynamic Nernst Formulation"),
      html("p", classes.p,
        "Standard Hodgkin-Huxley models treat <i>E</i><sub>K</sub> as a static constant (&minus;77 mV), assuming " +
        "extracellular fluid never changes. During action potentials K<sup>+</sup> rushes out into the extracellular " +
        "space, and metabolic stress causes Na<sup>+</sup>/K<sup>+</sup> pumps to malfunction, trapping excess " +
        "K<sup>+</sup> outside the cell. Modelling this shift is necessary to explain clinical realities like " +
        "drug-resistant epilepsy, where seizures stem from ionic buildup rather than faulty channel gates."),
      html("p", classes.p,
        "Replacing static <i>E</i><sub>K</sub> with a dynamic Nernst model at physiological temperature " +
        "(<i>T</i> = 310.15 K):"),
      html("div", classes.equation,
        "<i>E</i><sub>K</sub> = " + frac("<i>R</i>&thinsp;<i>T</i>", "<i>z</i>&thinsp;<i>F</i>") +
        " ln" + bigParen(frac(KO, KI)) +
        " = 26.7 &middot; ln" + bigParen(frac(KO, "140"))),
      html("p", classes.p,
        '<strong class="font-extrabold text-gray-950">Physiological impact.</strong> ' +
        "Under healthy conditions, active pumps keep extracellular potassium at 3.5 mM " +
        "(<i>E</i><sub>K</sub> = &minus;98.5 mV). Pump malfunction traps extruded potassium, driving " +
        KO + " to 12.0 mM and shifting <i>E</i><sub>K</sub> to &minus;65.6 mV. The resulting " +
        "<strong>+32.9 mV</strong> depolarizing shift weakens the repolarizing driving force " +
        "(<i>V</i> &minus; <i>E</i><sub>K</sub>), preventing the membrane potential from resetting and " +
        "trapping the cell in continuous seizure firing."),
    );

    // ---- analytical solution under voltage clamp ----
    const AX = "&alpha;<sub>x</sub>", BX = "&beta;<sub>x</sub>";
    const subHead = (t) => {
      const h = el("h4", "mb-2 font-mono text-lg font-black text-gray-950", t);
      h.style.marginTop = "1.9rem";
      return h;
    };
    const point = (term, detail) => {
      const row = el("div", "flex gap-3");
      row.append(
        el("span", "mt-[9px] h-1.5 w-1.5 shrink-0 rounded-full bg-red-600"),
        html("p", "text-[18px] leading-relaxed text-gray-800",
          '<strong class="font-extrabold text-gray-950">' + term + "</strong> — " + detail),
      );
      return row;
    };

    const framing = el("div", "mt-8");
    framing.append(
      el("h3", classes.h3, "Analytical Solution Under Voltage Clamp"),
      html("p", classes.p,
        "When membrane voltage is held constant at <i>V</i><sub>clamp</sub>, simulating a voltage-clamp experiment, " +
        "the gating rate functions " + AX + "(<i>V</i>) and " + BX + "(<i>V</i>) for " +
        "<i>x</i> &isin; {<i>m</i>, <i>h</i>, <i>n</i>} become constant coefficients."),

      subHead("The Simplified Linear ODE"),
      html("p", classes.p,
        "Under constant voltage the gating differential equation simplifies from a coupled non-linear system " +
        "into a first-order linear ordinary differential equation:"),
      html("div", classes.equation,
        frac("d<i>x</i>", "d<i>t</i>") + " = " + AX + "(1 &minus; <i>x</i>) &minus; " + BX + "<i>x</i>"),
      html("p", classes.p, "Rearranging terms into standard linear form yields:"),
      html("div", classes.equation,
        frac("d<i>x</i>", "d<i>t</i>") + " + (" + AX + " + " + BX + ")<i>x</i> = " + AX),

      subHead("Exact Closed-Form Solution"),
      html("p", classes.p,
        "Integrating this linear ODE gives the exact closed-form expression for gate opening probability over time:"),
      html("div", classes.equation,
        "<i>x</i>(<i>t</i>) = <i>x</i><sub>&infin;</sub> + (<i>x</i><sub>0</sub> &minus; <i>x</i><sub>&infin;</sub>)" +
        "&thinsp;e<sup>&minus;<i>t</i>&thinsp;/&thinsp;&tau;<sub>x</sub></sup>"),
      html("p", classes.p + " mt-4", "where:"),
    );

    const where = el("div", "mt-3");
    where.style.display = "grid";
    where.style.gridTemplateColumns = "max-content 1fr";
    where.style.columnGap = "26px";
    where.style.rowGap = "16px";
    where.style.alignItems = "baseline";

    const whereRow = (eq, text) => {
      const lhs = html("div", "", eq);
      lhs.style.fontFamily = '"Times New Roman", Times, serif';
      lhs.style.fontStyle = "italic";
      lhs.style.fontSize = "17px";
      lhs.style.whiteSpace = "nowrap";
      lhs.style.justifySelf = "start";
      const rhs = html("div", "", text);
      rhs.style.fontSize = "16px";
      rhs.style.lineHeight = "1.5";
      rhs.style.color = "#2b2f36";
      where.append(lhs, rhs);
    };

    whereRow(
      "<i>x</i><sub>&infin;</sub>(<i>V</i>) = " +
        frac(AX + "(<i>V</i>)", AX + "(<i>V</i>) + " + BX + "(<i>V</i>)"),
      "steady-state activation, the asymptotic open probability as <i>t</i> &rarr; &infin;");

    whereRow(
      "&tau;<sub>x</sub>(<i>V</i>) = " +
        frac("1", AX + "(<i>V</i>) + " + BX + "(<i>V</i>)"),
      "time constant, the rate of exponential relaxation toward steady state");

    whereRow(
      "<i>x</i><sub>0</sub> = <i>x</i>(0)",
      "initial state, the starting gating probability at <i>t</i> = 0");

    framing.appendChild(where);

    framing.append(
      subHead("Practical Significance"),
      html("p", classes.p,
        "This closed-form solution proves that under fixed voltage steps, channel gates relax exponentially " +
        "toward steady state (<i>x</i><sub>&infin;</sub>). We use it to calculate exact baseline initial conditions " +
        "(<i>m</i><sub>0</sub>, <i>h</i><sub>0</sub>, <i>n</i><sub>0</sub>) at resting potential " +
        "(<i>V</i> = &minus;70 mV) before initiating dynamic simulations."),
    );

    const numericalNote = el("div", "mt-8");
    numericalNote.append(
      el("h3", classes.h3, "Numerical Integration of the Full System"),
      html("p", classes.p,
        "During an action potential <i>V</i>(<i>t</i>) fluctuates freely. Gating states alter " +
        "<i>g</i><sub>Na</sub>(<i>m</i>, <i>h</i>) and <i>g</i><sub>K</sub>(<i>n</i>), which continuously update " +
        "d<i>V</i>/d<i>t</i>. Voltage and gating variables are non-linearly coupled through exponential functions, " +
        "so no closed form exists for the full system and numerical integration is required."),
    );

    body.append(
      formulation,
      termInspector,
      el("div", classes.divider),
      gates,
      el("div", classes.divider),
      nernst,
      el("div", classes.divider),
      framing,
      el("div", classes.divider),
      numericalNote,
    );
    section.appendChild(body);
  }

  function replaceBaseline() {
    const section = document.getElementById("timeline");
    if (!section) return;

    // Section 2 opener, inserted after the section label.
    if (section.dataset.apIntroAdded !== "true") {
      section.dataset.apIntroAdded = "true";
      const opener = el("div", "mb-6");
      opener.append(
        el("h3", classes.h3, "Action Potential Dynamics"),
        html("p", classes.p,
          "Depolarization past threshold (\u2248 \u221255 mV) triggers an all-or-nothing voltage spike " +
          "that propagates without attenuation."),
      );
      const anchor = section.firstElementChild;
      if (anchor && anchor.nextSibling) section.insertBefore(opener, anchor.nextSibling);
      else section.appendChild(opener);
    }
    const chronologyModule = section.querySelector("#action-potential-timeline-verification");
    const gateStateLabel = chronologyModule
      ? Array.from(chronologyModule.querySelectorAll("span")).find((node) =>
          node.textContent?.includes("Sodium Channel State Chronology"),
        )
      : null;
    gateStateLabel?.parentElement?.remove();
    const concisePhaseDescriptions = [
      "Membrane voltage remains near −70 mV while ionic currents are balanced.",
      "Rapid Na⁺ entry raises the membrane potential toward +40 mV.",
      "K⁺ exits as sodium channels close, returning voltage toward rest.",
      "Continued K⁺ efflux briefly lowers voltage below rest before recovery.",
    ];
    chronologyModule
      ?.querySelectorAll(":scope > div:first-child button p")
      .forEach((paragraph, index) => {
        if (concisePhaseDescriptions[index]) paragraph.textContent = concisePhaseDescriptions[index];
      });
    if (chronologyModule && chronologyModule.children.length >= 2) {
      const graphColumn = chronologyModule.children[1];
      const graphCard = graphColumn.firstElementChild;
      const chart = graphCard?.children[1];

      chronologyModule.className = "grid grid-cols-1 md:grid-cols-12 gap-8 items-start font-sans";
      graphColumn.className = "md:col-span-12 lg:col-span-7 flex flex-col";
      if (graphCard) {
        graphCard.className = "border border-gray-200 bg-white p-6 flex flex-col gap-4";
      }
      if (chart) {
        chart.style.paddingLeft = "1rem";
      }
    }

    section.innerHTML = "";
    section.className = classes.section;
    section.appendChild(label("BASELINE MODEL RESULTS"));

    const body = el("div", "space-y-6");
    const chronology = el("div", "space-y-4");
    if (chronologyModule) chronology.appendChild(chronologyModule);

    body.appendChild(chronology);
    section.appendChild(body);
  }

  function html(tag, cls, markup) {
    const node = el(tag, cls);
    node.innerHTML = markup;
    return node;
  }

  function createFigureCard(number, title, visual, caption, className = "") {
    // Flat figure: the parent section already provides the single surrounding box.
    const card = el("figure", "my-6 " + className);
    const heading = el("div", "mb-3");
    heading.append(
      el("div", classes.h4, "Figure " + number),
      el("h4", "text-xl font-extrabold text-gray-950", title),
    );
    const visualWrap = el("div", "");
    visualWrap.appendChild(visual);
    const description = el(
      "figcaption",
      "mt-3 text-[17px] leading-relaxed text-gray-700",
      caption,
    );
    card.append(heading, visualWrap, description);
    return card;
  }

  function createAssetPlot(src, alt) {
    const image = el("img", "block h-auto w-full bg-white");
    image.src = src;
    image.alt = alt;
    image.loading = "lazy";
    image.decoding = "async";
    image.style.aspectRatio = "16 / 10";
    image.style.objectFit = "contain";
    return image;
  }

  function createDataTable(title, columns, rows, note = "") {
    const wrap = el("div", "my-5");
    if (title) {
      const heading = el("div", "mb-2 font-mono text-sm font-black uppercase tracking-wide text-red-600", title);
      wrap.appendChild(heading);
    }
    const scroller = el("div", "overflow-x-auto");
    const table = el("table", "w-full min-w-[620px] border-collapse text-left text-[17px]");
    const thead = el("thead", "bg-gray-50");
    const headerRow = el("tr");
    columns.forEach((column) => {
      const th = el("th", "border-b border-gray-300 pr-5 py-3 font-mono text-[13px] font-black uppercase tracking-wide text-gray-700");
      th.innerHTML = column;
      headerRow.appendChild(th);
    });
    thead.appendChild(headerRow);
    const tbody = el("tbody", "divide-y divide-gray-100");
    rows.forEach((row) => {
      const tr = el("tr");
      row.forEach((cell) => {
        const td = el("td", "pr-5 py-3 align-top text-gray-700");
        td.innerHTML = cell;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.append(thead, tbody);
    scroller.appendChild(table);
    wrap.appendChild(scroller);
    if (note) {
      const caption = el("p", "mt-2 text-[15px] leading-relaxed text-gray-500");
      caption.innerHTML = note;
      wrap.appendChild(caption);
    }
    return wrap;
  }

  function createLinePlot(config) {
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", "0 0 680 330");
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", config.ariaLabel || config.title || "Data plot");
    svg.classList.add("block", "h-auto", "w-full", "bg-white");

    const bounds = { left: 72, right: 646, top: 30, bottom: 270 };
    const width = bounds.right - bounds.left;
    const height = bounds.bottom - bounds.top;
    const xScale = (value) =>
      bounds.left + ((value - config.xMin) / (config.xMax - config.xMin)) * width;
    const yScale = (value) =>
      bounds.bottom - ((value - config.yMin) / (config.yMax - config.yMin)) * height;
    const add = (name, attrs, textValue) => {
      const node = document.createElementNS(svgNS, name);
      Object.entries(attrs || {}).forEach(([key, value]) => node.setAttribute(key, value));
      if (textValue !== undefined) node.textContent = textValue;
      svg.appendChild(node);
      return node;
    };

    add("rect", { x: 0, y: 0, width: 680, height: 330, fill: "#ffffff" });
    (config.yTicks || []).forEach((tick) => {
      const y = yScale(tick);
      add("line", { x1: bounds.left, y1: y, x2: bounds.right, y2: y, stroke: "#e5e7eb" });
      add(
        "text",
        { x: bounds.left - 12, y: y + 4, "text-anchor": "end", fill: "#6b7280", "font-size": 12 },
        String(tick),
      );
    });
    (config.xTicks || []).forEach((tick) => {
      const x = xScale(tick);
      add("line", { x1: x, y1: bounds.top, x2: x, y2: bounds.bottom, stroke: "#f3f4f6" });
      add(
        "text",
        { x, y: bounds.bottom + 22, "text-anchor": "middle", fill: "#6b7280", "font-size": 12 },
        String(tick),
      );
    });
    add("line", { x1: bounds.left, y1: bounds.bottom, x2: bounds.right, y2: bounds.bottom, stroke: "#111827", "stroke-width": 1.5 });
    add("line", { x1: bounds.left, y1: bounds.top, x2: bounds.left, y2: bounds.bottom, stroke: "#111827", "stroke-width": 1.5 });

    config.series.forEach((series) => {
      const points = series.values
        .map(([x, y]) => xScale(x).toFixed(2) + "," + yScale(y).toFixed(2))
        .join(" ");
      add("polyline", {
        points,
        fill: "none",
        stroke: series.color,
        "stroke-linecap": "round",
        "stroke-linejoin": "round",
        "stroke-width": series.width || 3,
      });
    });

    add(
      "text",
      { x: (bounds.left + bounds.right) / 2, y: 318, "text-anchor": "middle", fill: "#374151", "font-size": 13, "font-weight": 700 },
      config.xLabel,
    );
    const yTitle = add(
      "text",
      { x: 18, y: (bounds.top + bounds.bottom) / 2, "text-anchor": "middle", fill: "#374151", "font-size": 13, "font-weight": 700 },
      config.yLabel,
    );
    yTitle.setAttribute("transform", "rotate(-90 18 " + (bounds.top + bounds.bottom) / 2 + ")");

    let legendX = bounds.left + 10;
    config.series.forEach((series) => {
      add("line", { x1: legendX, y1: 18, x2: legendX + 24, y2: 18, stroke: series.color, "stroke-width": 3 });
      add("text", { x: legendX + 31, y: 22, fill: "#374151", "font-size": 12, "font-weight": 700 }, series.label);
      legendX += 102;
    });
    return svg;
  }

